import {
  Component,
  ViewChild,
  ElementRef,
  ChangeDetectionStrategy,
} from '@angular/core';

import { toPng } from 'html-to-image';

import { avatarOptions, buildAvatar } from './avatar-utils';
import { AvatarDecoratorItem, AvatarOptions } from './avatar-types';

@Component({
  selector: 'wgj-avatar-generator',
  templateUrl: './avatar-generator.component.html',
  styleUrls: ['./avatar-generator.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AvatarGeneratorComponent {
  @ViewChild('screen') screen!: ElementRef;
  @ViewChild('canvas') canvas!: ElementRef;
  @ViewChild('downloadLink') downloadLink!: ElementRef;
  avatar = avatarOptions;
  bgImages = ['fondo1.png', 'fondo2.png', 'fondo3.png', 'fondo4.png'];
  bgImage = this.bgImages[0];
  avatarKeys = Object.keys(avatarOptions);

  downloadImage(): void {
    toPng(this.screen.nativeElement)
      .then((dataUrl) => {
        this.canvas.nativeElement.src = dataUrl;
        this.downloadLink.nativeElement.href = dataUrl;
        this.downloadLink.nativeElement.download = 'wgj-bolivia-avatar.png';
        this.downloadLink.nativeElement.click();
      })
      .catch((error) => console.error('oops, something went wrong!', error));
  }

  previousBgImage(): void {
    const index = this.bgImages.indexOf(this.bgImage);
    this.bgImage =
      this.bgImages[index - 1] || this.bgImages[this.bgImages.length - 1];
  }

  nextBgImage(): void {
    const index = this.bgImages.indexOf(this.bgImage);
    this.bgImage = this.bgImages[index + 1] || this.bgImages[0];
  }

  getAvatarDecoratorItem(key: string): AvatarDecoratorItem {
    return this.avatar[key as keyof AvatarOptions];
  }

  buildAvatarSvg(): string {
    return buildAvatar(this.avatar);
  }
}
<div class="container avatar">
  <div class="avatar__first-section">
    <wgj-section-title data-aos="fade-up">
      Crea tu propio avatar
    </wgj-section-title>

    <div class="avatar__chats" data-aos="fade-up">
      <div class="avatar__chat">
        <div class="nes-balloon from-left avatar__balloon">
          <p>
            Desarrollamos esta herramienta para que puedas crear tu avatar.
          </p>
        </div>
        <div class="avatar__kid">
          <img src="assets/img/girl-3.png" alt="niña pixelada" />
        </div>
      </div>

      <div class="avatar__chat avatar__chat--right">
        <div class="nes-balloon from-right avatar__balloon">
          <p>
            Úsalo en tu cuenta de Discord para interactuar con todos y todas las
            participantes.
          </p>
        </div>
        <div class="avatar__kid">
          <img src="assets/img/boy-1.png" alt="niño pixelado" />
        </div>
      </div>
    </div>
  </div>

  <div class="avatar__second-section">
    <div class="avatar__profile">
      <div
        #screen
        class="avatar__bg-image"
        [ngStyle]="{
          'background-image': 'url(/assets/img/' + bgImage + ')'
        }"
      >
        <div [innerHTML]="buildAvatarSvg() | sanitizeHtml"></div>
      </div>
      <div class="avatar__download-container">
        <div
          class="avatar__arrow avatar__arrow--flip"
          (click)="previousBgImage()"
        >
          <img src="assets/img/title-arrow.png" alt="arrow" />
        </div>
        <button
          type="button"
          class="avatar__download-button"
          (click)="downloadImage()"
        >
          Descargar avatar
        </button>
        <div class="avatar__arrow" (click)="nextBgImage()">
          <img src="assets/img/title-arrow.png" alt="arrow" />
        </div>
      </div>
    </div>
    <div class="avatar__items">
      <div *ngFor="let key of avatarKeys">
        <wgj-attribute-selector
          [dialogId]="key"
          [avatar]="avatar"
          [decorator]="getAvatarDecoratorItem(key)"
        ></wgj-attribute-selector>
      </div>
    </div>
  </div>
</div>

<div hidden>
  <img #canvas />
  <a #downloadLink>Descarga</a>
</div>
